We use the `hex`/`unhex` functions to handle binary data in ClickHouse, but this approach is not ideal. I would like to inquire if there is a better solution available before https://github.com/ClickHouse/clickhouse-js/issues/216 is completed.

```js
import { createClient } from '@clickhouse/client';

void (async () => {
  const client = createClient();

  await client.command({ query: `DROP TABLE IF EXISTS test_buffer` });
  await client.command({ query: `CREATE TABLE IF NOT EXISTS test_buffer (value FixedString(32)) ENGINE = Memory` });

  const values = [
    Buffer.from(crypto.getRandomValues(new Uint8Array(32))),
    Buffer.from(crypto.getRandomValues(new Uint8Array(32))),
    Buffer.from(crypto.getRandomValues(new Uint8Array(32))),
  ];

  // to hex
  const insertValues = values.map((v) => `(unhex('${v.toString('hex')}'))`).join('');

  // insert
  await client.command({
    query: `INSERT INTO test_buffer (value) VALUES ${insertValues}`,
  });

  const resultSet = await client.query({ query: 'SELECT hex(value) as value from test_buffer' });
  const json = await resultSet.json();
  json.data.forEach((item, i) => {
    const insertBuf = values[i];
    const resultBuf = Buffer.from(item.value, 'hex');
    console.log(resultBuf.equals(insertBuf));
  });

  await client.command({ query: `DROP TABLE IF EXISTS test_buffer` });
  await client.close();
})();
```

